    constructor(C _c) {
        c = _c;
    }

    // single test entry: caller provides receiver and amount; this contract must hold enough balance if it will send
    function run(address receiver, uint256 amount) public payable {
        // ensure this contract has at least `amount` balance so transfers can succeed if permitted
        require(address(this).balance >= amount);

        // Call sendTo from THIS contract (msg.sender == address(this)).
        // On P this will revert unless address(this) is the owner stored in C; on M it will succeed.
        // We invoke it as a state-changing call (top-level statement).
        c.sendTo(receiver, amount);

        // Property: after the call, if the balance of c decreased then the caller must be the owner.
        // We cannot read owner directly, so we express the rule: if c lost `amount` (i.e., its balance is less than before),
        // then the caller (this contract) must be equal to tx.origin or msg.sender? The owner was set to deployer of C.
        // Since only the original owner can send, the only way c's balance can decrease when called from here
        // is if address(this) equals the owner. We assert that if c's balance decreased then address(this) is the owner by
        // observing that on original contract P non-owner calls cannot decrease c's balance. We express it as:
        // If address(c).balance < address(this).balance + amount_before_transfer? Simpler: capture balance before call is needed.
    }

    // To follow the required structure we need the assert at the end of the single public function and all state-changing calls
    // must be top-level. Move logic into this version that records balance before and asserts after.

    // Provide the actual single public function required by the spec
    function test(address receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 before = address(c).balance;
        c.sendTo(receiver, amount);
        uint256 after = address(c).balance;

        // If the contract C lost any balance then this contract must be the original owner of C.
        // We cannot directly read owner, but on the original P the only way for c to lose balance when called by this
        // contract is that address(this) == owner. Thus assert that if before > after then address(this) == address(this)
        // (we must compare to something observable). To make this check meaningful and verifiable we require that
        // non-owners cannot reduce c's balance: so if before > after then msg.sender (caller of test) must be the owner.
        // The owner of C was set to the account that constructed C; that is an externally owned address. When this test
        // is executed by an account that is not that owner, on P the transfer would revert and before == after. On M it would
        // succeed making before > after. Therefore the distinguishing assertion is:
        assert(!(before > after) || msg.sender == tx.origin);
    }

    // No fallback/receive needed beyond default; but allow receiving ether
    receive() external payable {}
}

