        // We express this as a single assertion the reference satisfies for ALL inputs and the mutant violates for some inputs.
        address owner = address(uint160(vm.addr(1))); // dummy to avoid unused; actual owner is deployer (this contract)

        // Determine actual owner by reading storage is not possible; but we know owner was set to deployer (address(this) in setUp when new C() executed is this test contract)
