    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an attacker address (as bytes20 -> address) and an amount
    function testFuzz_property(address attacker, address receiver, uint256 amount) public {
        // keep addresses non-zero and distinct to avoid degenerate trivialities
        vm.assume(attacker != address(0));
        vm.assume(receiver != address(0));
        vm.assume(attacker != receiver);

        // bound the amount to a reasonable range so vm.deal and transfers make sense
        amount = bound(amount, 0, 1 ether);

        // Fund the contract with exactly `amount` so sending that amount would change balance
        // Use the deployer (this) as owner; c was deployed in setUp by this test contract
        vm.deal(address(this), amount);
        // send funds into c
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // Deploy an adversarial helper that will act as the caller (non-owner) and forward to c
        AttackerHelper helper = new AttackerHelper(c);
        // ensure helper has some ETH to pay for gas if needed (not required) and optionally to receive refunds
        vm.deal(address(helper), 0);

        // The property: Only the owner (this test contract, deployer) can make sendTo succeed and reduce address(c).balance
        // So when a non-owner (helper) calls sendTo to transfer `amount` to `receiver`, the correct contract MUST revert or fail
        // and thus address(c).balance must remain equal to `amount`. We perform the non-owner call via the helper and observe outcome.

        // Have helper attempt the call as non-owner. It will try to invoke c.sendTo(receiver, amount).
        bool ok;
        try helper.callSendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the correct contract, non-owner calls must NOT succeed in transferring funds. Therefore either the call reverts
        // or address(c).balance remains unchanged. We assert that the call did NOT succeed (ok == false) OR the contract balance stayed intact.
        // This single assertTrue captures the invariant: for all admissible inputs, non-owner attempt does not reduce address(c).balance.
        uint256 bal = address(c).balance;
        // assert: either call failed, or balance unchanged (still equal to amount)
        assertTrue((ok == false) || (bal == amount));
    }
}

